/** Date filters shared by the dashboard and embeddable aggregation API. Dates use UTC. */
export type AnalyticsRangeParams = {
	range?: "today" | "7d" | "30d" | "custom";
	start?: string;
	end?: string;
	path?: string;
	limit?: number;
	/** Server-assigned deployment environment. Omit for all environments. */
	environment?: string;
};

/** One UTC day of traffic. */
export type AnalyticsSeriesPoint = {
	date: string;
	pageViews: number;
	visitors: number;
	bounceRate?: number;
	sessionDuration?: number;
};

/** Page traffic and daily page-view counts for a sparkline. */
export type AnalyticsTopPage = {
	path: string;
	views: number;
	visitors: number;
	trend: number[];
};

/** External referrer host and its traffic. */
export type AnalyticsTopReferrer = {
	referrer: string;
	views: number;
	visitors: number;
};

/** Custom event name and number of occurrences. */
export type AnalyticsTopEvent = {
	name: string;
	count: number;
	/** Distinct daily anonymous session identifiers. */
	visitors?: number;
};

/** Ranked audience or acquisition dimension; missing values are labeled Unknown. */
export type AnalyticsDimension =
	| "country"
	| "device"
	| "browser"
	| "operatingSystem"
	| "hostname"
	| "route"
	| "utmSource"
	| "utmMedium"
	| "utmCampaign"
	| "utmTerm"
	| "utmContent";
export type AnalyticsDimensionRow = {
	value: string;
	visitors: number;
	views: number;
	trend?: number[];
};
export type AnalyticsMetric =
	| "uniqueVisitors"
	| "pageViews"
	| "bounceRate"
	| "sessionDuration";

/** Aggregated traffic. Duration is in seconds and bounce rate is a percentage. */
export type AnalyticsDashboardStats = {
	uniqueVisitors: number;
	pageViews: number;
	bounceRate: number;
	sessionDuration: number;
	series: AnalyticsSeriesPoint[];
	topPages: AnalyticsTopPage[];
	topReferrers: AnalyticsTopReferrer[];
	topEvents: AnalyticsTopEvent[];
	/** Equal-duration preceding window; null when outside retention or without views. */
	previous?: Record<AnalyticsMetric, number> | null;
	comparison?: { start: string; end: string };
	dimensions?: Record<AnalyticsDimension, AnalyticsDimensionRow[]>;
	/** Environments observed in this date range, before the environment filter. */
	environments?: string[];
};

/** Raw page-view record. Session IDs are irreversibly hashed before insertion. */
export type AnalyticsPageView = {
	id: string;
	path: string;
	referrer?: string | null;
	country?: string | null;
	device?: string | null;
	browser?: string | null;
	operatingSystem?: string | null;
	hostname?: string | null;
	route?: string | null;
	environment?: string | null;
	utmSource?: string | null;
	utmMedium?: string | null;
	utmCampaign?: string | null;
	utmTerm?: string | null;
	utmContent?: string | null;

	sessionId: string;
	timestamp: Date;
};

/** Raw custom-event record. Properties contain serialized JSON. */
export type AnalyticsCustomEvent = {
	id: string;
	name: string;
	path: string;
	properties?: string | null;
	environment?: string | null;
	sessionId: string;
	timestamp: Date;
};

/** Literal matchers for ordered anonymous-session funnels. Prefixes use startsWith. */
export type AnalyticsFunnelStep =
	| { type: "pageview"; path: string; match: "exact" | "prefix" }
	| { type: "event"; name: string };

/** Funnels accept 2–8 steps, at most 31 days, and a 1–1440 minute window. */
export type AnalyticsFunnelParams = Pick<
	AnalyticsRangeParams,
	"range" | "start" | "end" | "environment"
> & {
	windowMinutes: number;
	steps: readonly AnalyticsFunnelStep[];
};

/** Sessions are daily anonymous identifiers; totalSessions counts first-step entrants. */
export type AnalyticsFunnelResult = {
	start: string;
	end: string;
	windowMinutes: number;
	totalSessions: number;
	convertedSessions: number;
	conversionRate: number;
	steps: {
		step: AnalyticsFunnelStep;
		sessions: number;
		/** Percentage of first-step entrants. */
		conversionRate: number;
		/** Loss from the preceding step; zero for the first step. */
		dropOff: number;
		dropOffRate: number;
	}[];
};

/** Server-owned experiment definition, explicitly enabled alongside a flag resolver. */
export type AnalyticsExperimentDefinition = {
	key: string;
	flagKey: string;
	conversionEvent: string;
	/** First-exposure window, bounded by the current UTC day. @default 1800000 */
	attributionWindowMs?: number;
};

/** Persisted first meaningful exposure; sessionId is Analytics' daily anonymous hash. */
export type AnalyticsExperimentExposure = {
	id: string;
	dedupKey: string;
	experimentKey: string;
	flagKey: string;
	configurationVersion: string;
	variant: string;
	conversionEvent: string;
	attributionWindowMs: number;
	path: string;
	sessionId: string;
	timestamp: Date;
};

/** Accepted exposure activation; ownership follows these events without renewing the first-exposure window. */
export type AnalyticsExperimentActivation = {
	id: string;
	experimentKey: string;
	sessionId: string;
	exposureKey: string;
	timestamp: Date;
};

/** Descriptive counts for a single persisted experiment configuration and variant. */
export type AnalyticsExperimentVariantReport = {
	flagKey: string;
	configurationVersion: string;
	variant: string;
	conversionEvent: string;
	attributionWindowMs: number;
	subjects: number;
	exposures: number;
	conversions: number;
	/** Converted anonymous subjects divided by exposed subjects, as a percentage. */
	conversionRate: number;
};

/** Exposure cohort report; anonymous subjects are independent on each UTC day. */
export type AnalyticsExperimentReport = {
	experimentKey: string;
	flagKey: string;
	attribution: "same-session-utc-day";
	rows: AnalyticsExperimentVariantReport[];
};

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

/** Browser-safe permission descriptors for public ingestion and private analytics. */
export const analyticsPermissions = definePermissions("analytics", {
	events: {
		ingest: permission(z.object({ kind: z.enum(["pageview", "event"]) })),
		cleanup: permission(z.object({})),
	},
	experiments: {
		expose: permission(z.object({ experimentKey: z.string() })),
		read: permission(z.object({ experimentKey: z.string() })),
	},
	dashboard: {
		read: permission(z.object({})),
		export: permission(z.object({})),
	},
});

"use client";

import { useId } from "react";
import type { AnalyticsRangeParams } from "../../types";
import { useExperimentReport } from "@btst/plugin-analytics/client/hooks";

/** Protected experiment samples, grouped by persisted definition and variant. */
export function ExperimentReport({
	experimentKey,
	params,
}: {
	experimentKey: string;
	params: AnalyticsRangeParams;
}) {
	const titleId = useId();
	const { data, isPending, isFetching, isError, refetch } = useExperimentReport(
		{
			...params,
			experimentKey,
		},
	);
	return (
		<section
			className="analytics-table-section"
			aria-labelledby={titleId}
			aria-busy={isFetching}
		>
			<div className="analytics-section-heading">
				<h2 id={titleId}>Experiment: {experimentKey}</h2>
				<span>Descriptive conversion report · all environments</span>
			</div>
			{isError ? (
				<div role="alert">
					<p>
						Experiment report unavailable. Check your access and configuration.
					</p>
					<button type="button" onClick={() => void refetch()}>
						Try again
					</button>
				</div>
			) : isPending ? (
				<p role="status">Loading experiment samples…</p>
			) : data ? (
				<>
					<p className="analytics-note">
						Attribution stays within one anonymous session and UTC day. Only
						conversions after exposure and within the listed window count. Each
						subject converts at most once per definition.
					</p>
					<div className="analytics-table-scroll">
						<table aria-label={`Variant conversions for ${experimentKey}`}>
							<thead>
								<tr>
									<th scope="col">Variant</th>
									<th scope="col">Flag</th>
									<th scope="col">Definition</th>
									<th scope="col">Conversion event</th>
									<th scope="col">Subjects</th>
									<th scope="col">Exposures</th>
									<th scope="col">Conversions</th>
									<th scope="col">Rate</th>
									<th scope="col">Window</th>
								</tr>
							</thead>
							<tbody>
								{data.rows.length ? (
									data.rows.map((row) => (
										<tr key={`${row.configurationVersion}:${row.variant}`}>
											<th scope="row" className="analytics-path">
												{row.variant}
											</th>
											<td className="analytics-path">{row.flagKey}</td>
											<td>
												<code title={row.configurationVersion}>
													{row.configurationVersion.slice(0, 12)}
												</code>
											</td>
											<td className="analytics-path">{row.conversionEvent}</td>
											<td>{row.subjects}</td>
											<td>{row.exposures}</td>
											<td>{row.conversions}</td>
											<td>{row.conversionRate.toFixed(1)}%</td>
											<td>{row.attributionWindowMs / 60000} min</td>
										</tr>
									))
								) : (
									<tr>
										<td colSpan={9}>No experiment exposures in this range.</td>
									</tr>
								)}
							</tbody>
						</table>
					</div>
					<p className="analytics-note">
						Definition changes stay separate. These observations do not
						establish statistical significance or verify purchases.
					</p>
				</>
			) : null}
		</section>
	);
}

"use client";

import { useState, type FormEvent } from "react";
import { PermissionAccess, useStack } from "@btst/stack/context";
import { analyticsPermissions } from "../../permissions";
import type {
	AnalyticsFunnelParams,
	AnalyticsFunnelStep,
	AnalyticsRangeParams,
} from "../../types";
import { ANALYTICS_PLUGIN_ID } from "../constants";
import { useFunnelReport } from "@btst/plugin-analytics/client/hooks";

const number = new Intl.NumberFormat("en");

export function FunnelReport({ range }: { range: AnalyticsRangeParams }) {
	const [steps, setSteps] = useState<AnalyticsFunnelStep[]>([
		{ type: "pageview", path: "/", match: "exact" },
		{ type: "event", name: "" },
	]);
	const [windowMinutes, setWindowMinutes] = useState("30");
	const [request, setRequest] = useState<AnalyticsFunnelParams | null>(null);
	const [exporting, setExporting] = useState(false);
	const [exportError, setExportError] = useState("");
	const report = useFunnelReport(request);
	const { plugins } = useStack();
	const api = plugins?.[ANALYTICS_PLUGIN_ID]?.api;

	function updateSteps(next: AnalyticsFunnelStep[]) {
		setSteps(next);
		setRequest(null);
		setExportError("");
	}

	function run(event: FormEvent) {
		event.preventDefault();
		const next = { ...range, steps, windowMinutes: Number(windowMinutes) };
		setExportError("");
		if (JSON.stringify(next) === JSON.stringify(request)) void report.refetch();
		else setRequest(next);
	}

	async function exportCSV() {
		if (!request) return;
		setExporting(true);
		setExportError("");
		try {
			const headers = new Headers(api?.browserHeaders);
			headers.set("content-type", "application/json");
			const response = await fetch(
				`${api?.baseURL ?? ""}${(api?.basePath ?? "/api/data").replace(/\/$/, "")}/analytics/funnel/export`,
				{
					method: "POST",
					headers,
					credentials: api?.credentials ?? "same-origin",
					body: JSON.stringify(request),
				},
			);
			if (!response.ok) throw new Error("Export failed");
			const url = URL.createObjectURL(await response.blob());
			const link = document.createElement("a");
			link.href = url;
			link.download = "analytics-funnel.csv";
			link.click();
			setTimeout(() => URL.revokeObjectURL(url), 1000);
		} catch {
			setExportError(
				"Funnel could not be exported. Check your export access and try again.",
			);
		} finally {
			setExporting(false);
		}
	}

	return (
		<section
			className="analytics-table-section analytics-funnel"
			aria-labelledby="analytics-funnel-title"
		>
			<div className="analytics-section-heading">
				<h2 id="analytics-funnel-title">Conversion funnel</h2>
				<span>Ordered steps · selected UTC date range</span>
			</div>
			<p className="analytics-note">
				Count each anonymous session once. Steps must happen in order within one
				UTC day. Choose up to 31 days.
			</p>
			<form onSubmit={run} className="analytics-funnel-form">
				{steps.map((step, index) => (
					<fieldset key={index} className="analytics-funnel-step">
						<legend>Step {index + 1}</legend>
						<label>
							Type
							<select
								value={step.type}
								onChange={(event) =>
									updateSteps(
										steps.map((current, position) =>
											position === index
												? event.target.value === "pageview"
													? { type: "pageview", path: "/", match: "exact" }
													: { type: "event", name: "" }
												: current,
										),
									)
								}
							>
								<option value="pageview">Page view</option>
								<option value="event">Custom event</option>
							</select>
						</label>
						{step.type === "pageview" ? (
							<>
								<label>
									Path
									<input
										value={step.path}
										required
										maxLength={2048}
										pattern="/.*"
										onChange={(event) =>
											updateSteps(
												steps.map((current, position) =>
													position === index
														? { ...step, path: event.target.value }
														: current,
												),
											)
										}
									/>
								</label>
								<label>
									Match
									<select
										value={step.match}
										onChange={(event) =>
											updateSteps(
												steps.map((current, position) =>
													position === index
														? {
																...step,
																match: event.target.value as "exact" | "prefix",
															}
														: current,
												),
											)
										}
									>
										<option value="exact">Exact path</option>
										<option value="prefix">Path prefix</option>
									</select>
								</label>
							</>
						) : (
							<label>
								Event name
								<input
									value={step.name}
									placeholder="e.g. signup_completed"
									required
									maxLength={100}
									onChange={(event) =>
										updateSteps(
											steps.map((current, position) =>
												position === index
													? { ...step, name: event.target.value }
													: current,
											),
										)
									}
								/>
							</label>
						)}
						<button
							type="button"
							disabled={steps.length <= 2}
							aria-label={`Remove step ${index + 1}`}
							onClick={() =>
								updateSteps(steps.filter((_, position) => position !== index))
							}
						>
							Remove
						</button>
					</fieldset>
				))}
				<div className="analytics-funnel-actions">
					<button
						type="button"
						disabled={steps.length >= 8}
						onClick={() => updateSteps([...steps, { type: "event", name: "" }])}
					>
						Add step
					</button>
					<label>
						Conversion window (minutes)
						<input
							type="number"
							required
							min={1}
							max={1440}
							step={1}
							value={windowMinutes}
							onChange={(event) => {
								setWindowMinutes(event.target.value);
								setRequest(null);
							}}
						/>
					</label>
					<button type="submit" disabled={report.isFetching}>
						{report.isFetching ? "Running funnel…" : "Run funnel"}
					</button>
					<PermissionAccess
						permission={analyticsPermissions.dashboard.export({})}
					>
						<button
							type="button"
							disabled={
								!request ||
								!report.data ||
								!!report.error ||
								report.isFetching ||
								exporting
							}
							onClick={() => {
								void exportCSV();
							}}
						>
							{exporting ? "Exporting funnel…" : "Export funnel CSV"}
						</button>
					</PermissionAccess>
				</div>
			</form>
			{report.error && (
				<p role="alert" className="analytics-error">
					{report.error.message}
				</p>
			)}
			{exportError && (
				<p role="alert" className="analytics-error">
					{exportError}
				</p>
			)}
			{report.data && !report.error && (
				<div aria-live="polite" aria-busy={report.isFetching}>
					<p>
						<strong>
							{number.format(report.data.convertedSessions)} of{" "}
							{number.format(report.data.totalSessions)}
						</strong>{" "}
						sessions completed all steps ·{" "}
						{report.data.conversionRate.toFixed(1)}% conversion
					</p>
					{report.data.totalSessions === 0 && (
						<p role="status">
							No sessions matched the first step in this range.
						</p>
					)}
					<div className="analytics-table-scroll">
						<table>
							<caption className="analytics-sr-only">
								Ordered funnel results. Conversion is the share of sessions
								entering step 1; drop-off is from the previous step.
							</caption>
							<thead>
								<tr>
									<th scope="col">Step</th>
									<th scope="col">Sessions</th>
									<th scope="col">Conversion</th>
									<th scope="col">Drop-off</th>
								</tr>
							</thead>
							<tbody>
								{report.data.steps.map((result, index) => (
									<tr key={index}>
										<th scope="row">
											{index + 1}.{" "}
											{result.step.type === "pageview"
												? `${result.step.path}${result.step.match === "prefix" ? " (prefix)" : ""}`
												: result.step.name}
										</th>
										<td>{number.format(result.sessions)}</td>
										<td>{result.conversionRate.toFixed(1)}%</td>
										<td>
											{index === 0
												? "—"
												: `${number.format(result.dropOff)} (${result.dropOffRate.toFixed(1)}%)`}
										</td>
									</tr>
								))}
							</tbody>
						</table>
					</div>
				</div>
			)}
		</section>
	);
}

"use client";

import { useState, useRef, useEffect, type FormEvent } from "react";
import { useRegisterPageAIContext } from "@btst/stack/page-context";
import { PermissionAccess, useStack } from "@btst/stack/context";
import { analyticsPermissions } from "../../../permissions";
import type {
	AnalyticsRangeParams,
	AnalyticsMetric,
	AnalyticsDimension,
} from "../../../types";
import { RankedCard } from "../ranked-card";
import { TrafficChart } from "../traffic-chart";
import { FunnelReport } from "../funnel-report";
import { useRealtimeVisitors, useSuspenseDashboardStats } from "@btst/plugin-analytics/client/hooks";
import { ANALYTICS_PLUGIN_ID } from "../../constants";
import { ExperimentReport } from "../experiment-report";

const number = new Intl.NumberFormat("en");
const metricDefinitions: {
	key: AnalyticsMetric;
	label: string;
	description: string;
}[] = [
	{
		key: "uniqueVisitors",
		label: "Visitors",
		description:
			"Distinct anonymous session identifiers, not persistent people. Identifiers reset on reload and each UTC day.",
	},
	{
		key: "pageViews",
		label: "Page views",
		description: "Recorded page views, including repeat views.",
	},
	{
		key: "bounceRate",
		label: "Bounce rate",
		description:
			"Visits with exactly one page view divided by all visits. Custom events do not prevent a bounce.",
	},
	{
		key: "sessionDuration",
		label: "Session duration",
		description:
			"Average time between first and last page views. Single-page visits count as zero.",
	},
];
function FunnelDrawer({
	params,
	onClose,
}: {
	params: AnalyticsRangeParams;
	onClose: () => void;
}) {
	const dialog = useRef<HTMLDialogElement>(null);
	useEffect(() => {
		const element = dialog.current!;
		element.showModal();
		return () => element.close();
	}, []);
	return (
		<dialog
			ref={dialog}
			className="analytics-drawer"
			aria-label="Conversion funnel"
			onClose={onClose}
		>
			<div className="analytics-drawer-heading">
				<h2>Funnels</h2>
				<button
					type="button"
					onClick={() => dialog.current?.close()}
					aria-label="Close funnel"
				>
					Close
				</button>
			</div>
			<FunnelReport range={params} />
		</dialog>
	);
}

/** Dynamic dashboard; all displayed counts come from the authenticated API. */
export function AnalyticsDashboardPage({
	experiments = [],
}: {
	experiments?: string[];
} = {}) {
	const [params, setParams] = useState<AnalyticsRangeParams>({ range: "7d" });
	const [custom, setCustom] = useState(false);
	const [funnelOpen, setFunnelOpen] = useState(false);
	const [metric, setMetric] = useState<AnalyticsMetric>("uniqueVisitors");
	const [start, setStart] = useState(() =>
		new Date(Date.now() - 6 * 86400000).toISOString().slice(0, 10),
	);
	const [end, setEnd] = useState(() => new Date().toISOString().slice(0, 10));
	const [rangeError, setRangeError] = useState("");
	const [exportError, setExportError] = useState("");
	const [exporting, setExporting] = useState(false);
	const { data: stats, isFetching } = useSuspenseDashboardStats(params);
	const realtime = useRealtimeVisitors(params.environment);
	const { plugins } = useStack();
	const api = plugins?.[ANALYTICS_PLUGIN_ID]?.api;
	useRegisterPageAIContext({
		routeName: "analytics-dashboard",
		pageDescription: JSON.stringify({
			page: "Read-only Analytics dashboard summary. No mutation tools are available.",
			range: params,
			uniqueVisitors: stats.uniqueVisitors,
			pageViews: stats.pageViews,
			bounceRate: stats.bounceRate,
			sessionDurationSeconds: stats.sessionDuration,
			realtimeVisitors: realtime.data?.visitors,
		}),
	});

	function applyRange(event: FormEvent) {
		event.preventDefault();
		if (!start || !end || start > end) {
			setRangeError("Choose a start date on or before the end date.");
			return;
		}
		if (Date.parse(end) - Date.parse(start) > 366 * 86400000) {
			setRangeError("Choose a range of 366 days or fewer.");
			return;
		}
		setRangeError("");
		setParams({ ...params, range: "custom", start, end });
	}

	async function exportCSV() {
		setExporting(true);
		setExportError("");
		try {
			const query = new URLSearchParams();
			for (const [key, value] of Object.entries(params))
				if (value !== undefined) query.set(key, String(value));
			const url = `${api?.baseURL ?? ""}${(api?.basePath ?? "/api/data").replace(/\/$/, "")}/analytics/export?${query}`;
			const response = await fetch(url, {
				headers: api?.browserHeaders,
				credentials: api?.credentials ?? "same-origin",
			});
			if (!response.ok) throw new Error("Export failed");
			const download = URL.createObjectURL(await response.blob());
			const link = document.createElement("a");
			link.href = download;
			link.download = "analytics-events.csv";
			link.click();
			setTimeout(() => URL.revokeObjectURL(download), 1000);
		} catch {
			setExportError(
				"Events could not be exported. Check your export access and try again.",
			);
		} finally {
			setExporting(false);
		}
	}

	const dimension = (field: AnalyticsDimension) =>
		stats.dimensions?.[field] ?? [];
	const countryNames = new Intl.DisplayNames(["en"], { type: "region" });
	const formatMetric = (key: AnalyticsMetric, value: number) =>
		key === "bounceRate"
			? `${value.toFixed(1)}%`
			: key === "sessionDuration"
				? `${Math.floor(value / 60)}m ${Math.round(value % 60)}s`
				: number.format(value);
	return (
		<main
			className="analytics-dashboard"
			data-testid="analytics-dashboard"
			aria-busy={isFetching}
		>
			<header className="analytics-header">
				<div className="analytics-identity">
					<h1>Analytics</h1>
					<span
						className="analytics-live"
						aria-live="polite"
						title="Anonymous sessions with a page view in the last five minutes"
					>
						{realtime.isError ? (
							"Live count unavailable"
						) : realtime.data ? (
							<>
								<span aria-hidden="true" className="analytics-live-dot" />
								<strong>{number.format(realtime.data.visitors)}</strong> online
							</>
						) : (
							"Loading live count…"
						)}
					</span>
				</div>
				<div className="analytics-toolbar">
					<label className="analytics-sr-only" htmlFor="analytics-environment">
						Environment
					</label>
					<select
						id="analytics-environment"
						value={params.environment ?? ""}
						onChange={(event) =>
							setParams({
								...params,
								environment: event.target.value || undefined,
							})
						}
					>
						<option value="">All environments</option>
						{[
							...new Set([
								...(stats.environments ?? []),
								...(params.environment ? [params.environment] : []),
							]),
						].map((value) => (
							<option key={value} value={value}>
								{value}
							</option>
						))}
					</select>
					<label className="analytics-sr-only" htmlFor="analytics-range">
						Date range
					</label>
					<select
						id="analytics-range"
						value={custom ? "custom" : params.range}
						onChange={(event) => {
							const range = event.target.value as AnalyticsRangeParams["range"];
							setCustom(range === "custom");
							setRangeError("");
							if (range !== "custom")
								setParams(
									params.environment
										? { range, environment: params.environment }
										: { range },
								);
						}}
					>
						<option value="today">Today</option>
						<option value="7d">Last 7 days</option>
						<option value="30d">Last 30 days</option>
						<option value="custom">Custom</option>
					</select>
					<PermissionAccess
						permission={analyticsPermissions.dashboard.read({})}
					>
						<button type="button" onClick={() => setFunnelOpen(true)}>
							Funnels
						</button>
					</PermissionAccess>
					<PermissionAccess
						permission={analyticsPermissions.dashboard.export({})}
					>
						<details className="analytics-overflow">
							<summary aria-label="More analytics actions">•••</summary>
							<div>
								<button
									type="button"
									disabled={exporting}
									onClick={() => void exportCSV()}
								>
									{exporting ? "Exporting…" : "Export CSV"}
								</button>
							</div>
						</details>
					</PermissionAccess>
				</div>
			</header>
			{custom && (
				<form className="analytics-custom-range" onSubmit={applyRange}>
					<label>
						Start date
						<input
							type="date"
							value={start}
							max={end || undefined}
							onChange={(event) => setStart(event.target.value)}
							required
						/>
					</label>
					<label>
						End date
						<input
							type="date"
							value={end}
							min={start || undefined}
							onChange={(event) => setEnd(event.target.value)}
							required
						/>
					</label>
					<button type="submit">Apply dates</button>
					<span>Dates use UTC.</span>
				</form>
			)}
			{rangeError && (
				<p role="alert" className="analytics-error">
					{rangeError}
				</p>
			)}
			{exportError && (
				<p role="alert" className="analytics-error">
					{exportError}
				</p>
			)}
			<section className="analytics-overview" aria-label="Traffic overview">
				<div
					className="analytics-metrics"
					role="group"
					aria-label="Chart metric"
				>
					{metricDefinitions.map((item) => {
						const previous = stats.previous?.[item.key];
						const change = previous
							? ((stats[item.key] - previous) / previous) * 100
							: null;
						return (
							<button
								type="button"
								key={item.key}
								aria-pressed={metric === item.key}
								title={item.description}
								aria-describedby={`analytics-${item.key}-definition`}
								onClick={() => setMetric(item.key)}
							>
								<span>{item.label}</span>
								<div>
									<strong>{formatMetric(item.key, stats[item.key])}</strong>
									{change !== null ? (
										<small
											className={
												change === 0
													? ""
													: (
																item.key === "bounceRate"
																	? change < 0
																	: change > 0
															)
														? "analytics-change-positive"
														: "analytics-change-negative"
											}
											title={`Compared with preceding equal-duration period: ${stats.comparison?.start ?? ""} to ${stats.comparison?.end ?? ""}`}
										>
											{change > 0 ? "+" : ""}
											{change.toFixed(0)}%
										</small>
									) : (
										<small>No prior data</small>
									)}
								</div>
							</button>
						);
					})}
				</div>
				{stats.pageViews === 0 && (
					<p className="analytics-empty" role="status">
						No page views in this range. Visit a tracked page or choose another
						date range.
					</p>
				)}
				<TrafficChart
					page="analyticsDashboard"
					series={stats.series}
					metric={metric}
				/>
			</section>
			<div className="analytics-grid analytics-grid-two">
				<RankedCard
					title="Pages"
					tabs={[
						{
							label: "Pages",
							rows: stats.topPages.map((row) => ({
								value: row.path,
								visitors: row.visitors,
								views: row.views,
								trend: row.trend,
							})),
						},
						{ label: "Routes", rows: dimension("route") },
						{ label: "Hostnames", rows: dimension("hostname") },
					]}
				/>
				<RankedCard
					title="Acquisition"
					tabs={[
						{
							label: "Referrers",
							rows: stats.topReferrers.map((row) => ({
								value: row.referrer || "Direct",
								visitors: row.visitors,
								views: row.views,
							})),
						},
						...(
							[
								["utmSource", "UTM source"],
								["utmMedium", "Medium"],
								["utmCampaign", "Campaign"],
								["utmTerm", "Term"],
								["utmContent", "Content"],
							] as const
						).map(([key, label]) => ({ label, rows: dimension(key) })),
					]}
				/>
			</div>
			<div className="analytics-grid analytics-grid-three">
				<RankedCard
					title="Countries"
					tabs={[
						{
							label: "Countries",
							rows: dimension("country").map((row) => ({
								...row,
								value: /^[A-Z]{2}$/.test(row.value)
									? (countryNames.of(row.value) ?? row.value)
									: row.value,
							})),
						},
					]}
					percentageOf={stats.uniqueVisitors}
				/>
				<RankedCard
					title="Devices and browsers"
					tabs={[
						{ label: "Devices", rows: dimension("device") },
						{ label: "Browsers", rows: dimension("browser") },
					]}
					percentageOf={stats.uniqueVisitors}
				/>
				<RankedCard
					title="Operating systems"
					tabs={[
						{ label: "Operating systems", rows: dimension("operatingSystem") },
					]}
					percentageOf={stats.uniqueVisitors}
				/>
			</div>
			<section className="analytics-card analytics-events" aria-label="Events">
				<div className="analytics-card-heading">
					<h2>Events</h2>
					<span>Actions visitors took</span>
				</div>
				<div className="analytics-table-scroll">
					<table>
						<thead>
							<tr>
								<th scope="col">Event</th>
								<th scope="col">Visitors</th>
								<th scope="col">Total</th>
							</tr>
						</thead>
						<tbody>
							{stats.topEvents.length ? (
								stats.topEvents.map((event) => (
									<tr key={event.name}>
										<th scope="row">{event.name}</th>
										<td>
											{event.visitors === undefined
												? "—"
												: number.format(event.visitors)}
										</td>
										<td>{number.format(event.count)}</td>
									</tr>
								))
							) : (
								<tr>
									<td colSpan={3}>No custom events in this range.</td>
								</tr>
							)}
						</tbody>
					</table>
				</div>
			</section>
			{experiments.map((experimentKey) => (
				<PermissionAccess
					key={experimentKey}
					permission={analyticsPermissions.experiments.read({ experimentKey })}
				>
					<ExperimentReport
						experimentKey={experimentKey}
						params={{ ...params, environment: undefined }}
					/>
				</PermissionAccess>
			))}
			<details className="analytics-definitions">
				<summary>About these metrics</summary>
				{metricDefinitions.map((item) => (
					<p key={item.key} id={`analytics-${item.key}-definition`}>
						<strong>{item.label}:</strong> {item.description}
					</p>
				))}
				<p>
					Anonymous sessions are held in memory. No analytics cookies are
					created. Missing dimensions are shown as Unknown; old records cannot
					be backfilled. UTM labels describe the first page of each session.
					Comparisons use the preceding equal-duration window and require
					retained data.
				</p>
			</details>
			{funnelOpen && (
				<FunnelDrawer
					key={JSON.stringify(params)}
					params={params}
					onClose={() => setFunnelOpen(false)}
				/>
			)}
		</main>
	);
}

"use client";

import { lazy, useEffect, useState } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { analyticsPermissions } from "../../../permissions";

const Dashboard = lazy(() =>
	import("./dashboard-page.internal").then((module) => ({
		default: module.AnalyticsDashboardPage,
	})),
);

function Loading() {
	return (
		<div className="analytics-dashboard" role="status" aria-live="polite">
			<h1>Analytics</h1>
			<p>Loading traffic…</p>
		</div>
	);
}

function BrowserDashboard({ experiments }: { experiments?: string[] }) {
	const [mounted, setMounted] = useState(false);
	useEffect(() => setMounted(true), []);
	return mounted ? <Dashboard experiments={experiments} /> : <Loading />;
}

function ErrorState({
	resetErrorBoundary,
}: {
	resetErrorBoundary: () => void;
}) {
	return (
		<div className="analytics-dashboard" role="alert">
			<h1>Analytics unavailable</h1>
			<p>Traffic could not be loaded. Check your access and try again.</p>
			<button type="button" onClick={resetErrorBoundary}>
				Try again
			</button>
		</div>
	);
}

/** Dashboard route with authorization, loading and error boundaries. */
export function AnalyticsDashboardPageComponent({
	experiments,
}: {
	experiments?: string[];
} = {}) {
	return (
		<ComposedRoute
			path="/analytics"
			permission={analyticsPermissions.dashboard.read({})}
			PageComponent={BrowserDashboard}
			props={{ experiments }}
			ErrorComponent={ErrorState}
			LoadingComponent={Loading}
			onError={(error) => console.error("Analytics dashboard failed:", error)}
		/>
	);
}

"use client";

import { useId, useState } from "react";
import type { AnalyticsDimensionRow } from "../../types";

export function RankedCard({
	title,
	tabs,
	percentageOf,
}: {
	title: string;
	tabs: { label: string; rows: AnalyticsDimensionRow[] }[];
	percentageOf?: number;
}) {
	const id = useId();
	const [selected, setSelected] = useState(0);
	const [expanded, setExpanded] = useState(false);
	const tab = tabs[selected] ?? tabs[0]!;
	const rows = expanded ? tab.rows : tab.rows.slice(0, 5);
	const max = Math.max(1, ...tab.rows.map((row) => row.visitors));
	return (
		<section className="analytics-card" aria-label={title}>
			<div className="analytics-card-heading">
				<div
					role="group"
					aria-label={`${title} breakdown`}
					className="analytics-card-tabs"
				>
					{tabs.map((item, index) => (
						<button
							type="button"
							key={item.label}
							aria-pressed={index === selected}
							aria-controls={id}
							onClick={() => {
								setSelected(index);
								setExpanded(false);
							}}
						>
							{item.label}
						</button>
					))}
				</div>
				<span title="Distinct daily anonymous sessions">Visitors</span>
			</div>
			<div id={id} className="analytics-rank-list" aria-live="polite">
				{rows.length ? (
					rows.map((row) => (
						<div
							key={row.value}
							className="analytics-rank-row"
							title={`${row.value}: ${row.visitors} visitors, ${row.views} page views`}
						>
							<span
								className="analytics-rank-bar"
								aria-hidden="true"
								style={{ width: `${(row.visitors / max) * 100}%` }}
							/>
							<span className="analytics-rank-name">{row.value}</span>
							{row.trend && (
								<>
									<svg
										className="analytics-sparkline"
										viewBox="0 0 80 24"
										role="img"
										aria-label={`${row.value}: ${row.trend.join(", ")} page views by day`}
									>
										<polyline
											fill="none"
											stroke="currentColor"
											strokeWidth="1.5"
											points={row.trend
												.map(
													(value, index) =>
														`${(index * 78) / Math.max(1, row.trend!.length - 1) + 1},${22 - (value / Math.max(1, ...row.trend!)) * 20}`,
												)
												.join(" ")}
										/>
									</svg>
								</>
							)}
							<strong>
								{percentageOf
									? `${Math.round((row.visitors / percentageOf) * 100)}%`
									: row.visitors.toLocaleString("en")}
							</strong>
						</div>
					))
				) : (
					<p className="analytics-card-empty">No data in this range.</p>
				)}
			</div>
			{tab.rows.length > 5 && (
				<button
					type="button"
					className="analytics-show-more"
					aria-expanded={expanded}
					onClick={() => setExpanded(!expanded)}
				>
					{expanded ? "Show less" : `Show all ${tab.rows.length}`}
				</button>
			)}
		</section>
	);
}

"use client";

import { useState, useRef, useEffect } from "react";
import { usePluginOverrides } from "@btst/stack/context";
import { ANALYTICS_PLUGIN_ID } from "../constants";
import type {
	AnalyticsPluginOverrides,
	AnalyticsTrafficChartProps,
} from "../overrides";

const number = new Intl.NumberFormat("en");
const dateLabel = (date: string) =>
	new Intl.DateTimeFormat("en", {
		month: "short",
		day: "numeric",
		timeZone: "UTC",
	}).format(new Date(date));

export function TrafficChart({
	page,
	...props
}: AnalyticsTrafficChartProps & { page?: "analyticsDashboard" }) {
	return page ? (
		<ScopedTrafficChart page={page} {...props} />
	) : (
		<DefaultTrafficChart {...props} />
	);
}

function ScopedTrafficChart({
	page,
	...props
}: AnalyticsTrafficChartProps & { page: "analyticsDashboard" }) {
	const { pageOverrides } =
		usePluginOverrides<AnalyticsPluginOverrides>(ANALYTICS_PLUGIN_ID);
	const Component =
		(page ? pageOverrides?.[page]?.TrafficChart : undefined) ??
		DefaultTrafficChart;
	return <Component {...props} />;
}

function DefaultTrafficChart({
	series,
	metric = "pageViews",
}: AnalyticsTrafficChartProps) {
	const [active, setActive] = useState<number | null>(null);
	const svg = useRef<SVGSVGElement>(null);
	const [width, setWidth] = useState(960);
	useEffect(() => {
		if (typeof ResizeObserver === "undefined") return;
		const observer = new ResizeObserver(([entry]) => {
			if (entry) setWidth(Math.max(300, entry.contentRect.width));
		});
		observer.observe(svg.current!);
		return () => observer.disconnect();
	}, []);
	const label = {
		uniqueVisitors: "Visitors",
		pageViews: "Page views",
		bounceRate: "Bounce rate",
		sessionDuration: "Session duration",
	}[metric];
	const values = series.map((point) =>
		metric === "uniqueVisitors" ? point.visitors : (point[metric] ?? 0),
	);
	const max =
		metric === "bounceRate"
			? 100
			: Math.max(3, Math.ceil(Math.max(0, ...values) / 3) * 3);
	const x = (index: number) =>
		45 + (index * (width - 70)) / Math.max(1, series.length - 1);
	const y = (value: number) => 205 - (value / max) * 170;
	const points = values.map((value, index) => `${x(index)},${y(value)}`);
	const today = new Date().toISOString().slice(0, 10);
	const partial = series.at(-1)?.date === today;
	const format = (value: number) =>
		metric === "bounceRate"
			? `${value.toFixed(1)}%`
			: metric === "sessionDuration"
				? `${Math.round(value)}s`
				: number.format(value);
	const focused = active === null ? undefined : series[active];
	return (
		<section className="analytics-traffic" aria-label="Traffic over time">
			<div className="analytics-section-heading">
				<h2>Traffic over time</h2>
				<span>{label} per day · UTC</span>
			</div>
			<div className="analytics-chart-tooltip" aria-live="polite">
				{focused
					? `${dateLabel(focused.date)}: ${format(values[active!]!)} ${label.toLowerCase()}${focused.date === today ? " (day in progress)" : ""}`
					: "Hover or focus a day for details"}
			</div>
			<svg
				className="analytics-chart"
				ref={svg}
				viewBox={`0 0 ${width} 245`}
				role="group"
				aria-label={`Daily ${label.toLowerCase()} from ${series[0]?.date ?? "start"} to ${series.at(-1)?.date ?? "end"}. Peak ${format(Math.max(0, ...values))}.`}
			>
				{[0, 1, 2, 3].map((index) => {
					const value = (max * index) / 3;
					return (
						<g key={index}>
							<line
								x1="45"
								x2={width - 25}
								y1={y(value)}
								y2={y(value)}
								className="analytics-chart-rule"
							/>
							<text
								x="33"
								y={y(value) + 4}
								textAnchor="end"
								className="analytics-chart-axis"
							>
								{metric === "bounceRate"
									? `${Math.round(value)}%`
									: Math.round(value)}
							</text>
						</g>
					);
				})}
				{points.length > 0 && (
					<>
						<polygon
							points={`45,205 ${points.join(" ")} ${x(points.length - 1)},205`}
							className="analytics-chart-area"
						/>
						<polyline
							points={(partial && points.length > 1
								? points.slice(0, -1)
								: points
							).join(" ")}
							fill="none"
							stroke="currentColor"
							strokeWidth="2"
							vectorEffect="non-scaling-stroke"
						/>
						{partial && points.length > 1 && (
							<polyline
								points={points.slice(-2).join(" ")}
								fill="none"
								stroke="currentColor"
								strokeWidth="2"
								strokeDasharray="5 5"
								vectorEffect="non-scaling-stroke"
							/>
						)}
					</>
				)}
				{series.map((point, index) => (
					<g key={point.date}>
						{(index === 0 ||
							index === series.length - 1 ||
							index %
								Math.ceil(
									(series.length - 1) / Math.max(1, Math.floor(width / 100)),
								) ===
								0) && (
							<text
								x={x(index)}
								y="233"
								textAnchor="middle"
								className="analytics-chart-axis"
							>
								{dateLabel(point.date)}
							</text>
						)}
						<circle
							cx={x(index)}
							cy={y(values[index]!)}
							r={active === index || series.length === 1 ? 4 : 2}
							fill="currentColor"
						/>
						<circle
							cx={x(index)}
							cy={y(values[index]!)}
							r="12"
							fill="transparent"
							tabIndex={0}
							role="img"
							aria-label={`${dateLabel(point.date)}: ${format(values[index]!)} ${label.toLowerCase()}${point.date === today ? ", day in progress" : ""}`}
							onMouseEnter={() => setActive(index)}
							onMouseLeave={() => setActive(null)}
							onFocus={() => setActive(index)}
							onBlur={() => setActive(null)}
						>
							<title>{`${dateLabel(point.date)}: ${format(values[index]!)}`}</title>
						</circle>
					</g>
				))}
			</svg>
			<details className="analytics-chart-data">
				<summary>View daily counts</summary>
				<div className="analytics-table-scroll">
					<table>
						<thead>
							<tr>
								<th scope="col">Date (UTC)</th>
								<th scope="col">Page views</th>
								<th scope="col">Visitors</th>
								<th scope="col">Bounce rate</th>
							</tr>
						</thead>
						<tbody>
							{series.map((point) => (
								<tr key={point.date}>
									<th scope="row">{point.date}</th>
									<td>{number.format(point.pageViews)}</td>
									<td>{number.format(point.visitors)}</td>
									<td>
										{point.bounceRate === undefined
											? "—"
											: `${point.bounceRate.toFixed(1)}%`}
									</td>
								</tr>
							))}
						</tbody>
					</table>
				</div>
			</details>
		</section>
	);
}

import type { ComponentType } from "react";
import type { AnalyticsSeriesPoint, AnalyticsMetric } from "../types";

/** Traffic series supplied by the built-in dashboard. */
export interface AnalyticsTrafficChartProps {
	/** Daily page view and visitor totals. */
	series: AnalyticsSeriesPoint[];
	/** Selected metric. Defaults to pageViews for standalone chart consumers. */
	metric?: AnalyticsMetric;
}

/** Presentation customization for built-in analytics pages. */
export interface AnalyticsPluginOverrides {
	/** Replace only the dashboard chart, retaining filters, metrics, and tables. */
	pageOverrides?: {
		analyticsDashboard?: {
			TrafficChart?: ComponentType<AnalyticsTrafficChartProps>;
		};
	};
}
